import { createRouter, createWebHistory } from 'vue-router';
import CrowdsourcedAlerts from '@/views/CrowdsourcedAlerts.vue'; // Fixed path
import RoutePlanner from '@/views/RoutePlanner.vue'; // Fixed path
import LogisticsManagement from '@/views/LogisticsManagement.vue'; // Fixed path
import ShippingTracking from '@/views/ShippingTracking.vue'; // Fixed path

const routes = [
  { path: '/', redirect: '/route-planner' }, // Default route
  { path: '/route-planner', name: 'RoutePlanner', component: RoutePlanner },
  { path: '/logistics-management', name: 'LogisticsManagement', component: LogisticsManagement },
  { path: '/shipping-tracking', name: 'ShippingTracking', component: ShippingTracking },
  { path: '/crowdsourced-alerts', name: 'CrowdsourcedAlerts', component: CrowdsourcedAlerts },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

export default router;
